function batchAction(action){if(!selection.size)return;commit();if(action==='delete'){state.layers=state.layers.filter(l=>!selection.has(l.id));selection.clear();selected=undefined}else{const copies=selectedLayers().map(l=>({...structuredClone(l),id:uid(),name:l.name+' 副本'}));const delta=moveDelta(copies,16,16,state.width,state.height);copies.forEach(l=>{l.x+=delta.dx;l.y+=delta.dy});state.layers.push(...copies);selection=new Set(copies.map(l=>l.id));selected=copies.at(-1).id}render();changed()}
