function updateCrop(){if(!cropContext)return;cropContext.fx=Number($('#cropX').value);cropContext.fy=Number($('#cropY').value);$('#cropImage').style.objectPosition=`${cropContext.fx}% ${cropContext.fy}%`;$('#cropValues').textContent=`水平 ${Math.round(cropContext.fx)}% · 垂直 ${Math.round(cropContext.fy)}%`}
const parseSong=s=>String(s).match(/(?:[?&]id=|^)(\d+)(?:$|&)/)?.[1]||'';
const validAudio=s=>/^https:\/\/[^\s]+$/i.test(s)||/^data:audio\/[\w.+-]+;base64,[A-Za-z0-9+/=]+$/.test(s);
function validQQ(s){try{let u=new URL(s);return u.protocol==='https:'&&(['y.qq.com','c.y.qq.com','i.y.qq.com','music.qq.com'].includes(u.hostname))}catch{return false}}
