function addLayer(type){commit();const w=Math.min(654,state.width-48),x=Math.round((state.width-w)/2),y=Math.max(0,Math.min(Math.round($('#viewport').scrollTop/scale+180),state.height-150));const l={id:uid(),type,name:types[type],x,y,w,h:Math.min((type==='image'||type==='gallery'||['reveal','perspective','parallax'].includes(type))?400:type==='music'?290:type==='media'?220:70,state.height-y),radius:8};if(isEffect(l))normalizeEffect(l);if(type==='image')Object.assign(l,{images:[],fit:'cover'});if(type==='gallery')Object.assign(l,{images:[],mode:'horizontal',duration:4,fit:'cover'});if(type==='music')Object.assign(l,{title:'你的曲目名称',artist:'音乐人 / 专辑',source:'audio',audio:'',songId:'',link:''});if(type==='media')Object.assign(l,{mediaKind:'音频',title:'在此插入音频',artist:'公众号原生卡片'});if(type==='text')Object.assign(l,{text:'写下一段声音的注脚。',fontSize:24,color:'#425439',align:'left'});state.layers.push(l);selected=l.id;selection=new Set([l.id]);preview=false;setMode();render();changed()}
function readData(file){return new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
async function imageAsset(file){let src;if(file.type==='image/svg+xml'||/\.svg$/i.test(file.name)){const doc=new DOMParser().parseFromString(await file.text(),'image/svg+xml');if(doc.querySelector('parsererror')||doc.documentElement.localName!=='svg')throw Error('SVG 文件无效');const forbidden='script,foreignObject,iframe,object,embed,audio,video,animate,animateTransform,set';doc.querySelectorAll(forbidden).forEach(n=>n.remove());doc.querySelectorAll('*').forEach(n=>[...n.attributes].forEach(a=>{if(/^on/i.test(a.name)||((a.localName==='href')&&!/^#|^data:image\/(png|jpeg|webp);base64,/i.test(a.value))||/url\(\s*['"]?(?!#)/i.test(a.value))n.removeAttribute(a.name)}));doc.querySelectorAll('style').forEach(n=>n.remove());src=svgData(new XMLSerializer().serializeToString(doc.documentElement))}else{if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw Error('请选择 PNG、JPG、WEBP、GIF 或 SVG');src=await readData(file)}const img=await loadImg(src);if(!img.naturalWidth||!img.naturalHeight)throw Error('浏览器无法读取图片尺寸，请尝试分切片导入');return {id:uid(),name:file.name,src,url:'',width:img.naturalWidth,height:img.naturalHeight}}
