$('#cropX').oninput=$('#cropY').oninput=updateCrop;
$('#cropReset').onclick=()=>{$('#cropX').value=50;$('#cropY').value=50;updateCrop()};
$('#cropSave').onclick=()=>{if(cropContext){commit();Object.assign(cropContext.asset,{focusX:cropContext.fx,focusY:cropContext.fy});render();changed()}$('#cropDialog').close()};
$('#cropStage').onpointerdown=e=>{if(!cropContext||e.button!==0)return;e.preventDefault();const box=$('#cropStage').getBoundingClientRect(),c=cropContext,r=imageRect(c.iw,c.ih,box.width,box.height,c.layer.fit,c.fx,c.fy),start={x:e.clientX,y:e.clientY,fx:c.fx,fy:c.fy};const target=e.currentTarget;target.setPointerCapture(e.pointerId);target.onpointermove=ev=>{$('#cropX').value=Math.abs(box.width-r.w)>1?clamp(start.fx+(ev.clientX-start.x)/(box.width-r.w)*100,0,100):start.fx;$('#cropY').value=Math.abs(box.height-r.h)>1?clamp(start.fy+(ev.clientY-start.y)/(box.height-r.h)*100,0,100):start.fy;updateCrop()};target.onpointerup=target.onpointercancel=()=>target.onpointermove=null};
$('#snapToggle').onchange=e=>snapEnabled=e.target.checked;
$('#zoomIn').onclick=()=>{const r=$('#viewport').getBoundingClientRect();zoomAt(scale*1.2,r.left+r.width/2,r.top+r.height/2)};
$('#zoomOut').onclick=()=>{const r=$('#viewport').getBoundingClientRect();zoomAt(scale/1.2,r.left+r.width/2,r.top+r.height/2)};
$('#viewport').addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey||e.altKey){e.preventDefault();zoomAt(scale*Math.exp(-e.deltaY*.005),e.clientX,e.clientY)}},{passive:false});
const typing=e=>/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable;
document.addEventListener('keydown',e=>{if(typing(e)||$('dialog[open]'))return;if(e.code==='Space'){e.preventDefault();spaceDown=true;$('#viewport').classList.add('pan-ready')}if(!preview&&(e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='a'){e.preventDefault();selection=new Set(state.layers.map(l=>l.id));selected=state.layers.at(-1)?.id;render()}if(!preview&&(e.key==='Delete'||e.key==='Backspace')){e.preventDefault();batchAction('delete')}if(!preview&&(e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='d'){e.preventDefault();batchAction('copy')}if(e.key==='Escape'){selected=undefined;selection.clear();render()}});
const clearSpace=()=>{spaceDown=false;$('#viewport').classList.remove('pan-ready')};document.addEventListener('keyup',e=>{if(e.code==='Space')clearSpace()});window.addEventListener('blur',clearSpace);
$('#viewport').addEventListener('pointerdown',e=>{if(!spaceDown&&e.button!==1)return;e.preventDefault();e.stopPropagation();const v=$('#viewport'),start={x:e.clientX,y:e.clientY,left:v.scrollLeft,top:v.scrollTop};v.setPointerCapture(e.pointerId);v.classList.add('panning');v.onpointermove=ev=>{v.scrollLeft=start.left-(ev.clientX-start.x);v.scrollTop=start.top-(ev.clientY-start.y)};v.onpointerup=v.onpointercancel=()=>{v.onpointermove=null;v.classList.remove('panning')}},{capture:true});
$('#board').addEventListener('pointerdown',e=>{if(preview||spaceDown||e.button!==0||e.target.closest('.art-layer'))return;selectLayer(undefined)});
render();await initDB();extensionAssets();

$('#coverFile').onchange=async e=>{const l=current(),file=e.target.files[0];if(!file||l?.type!=='music')return;try{const cover=await imageAsset(file);commit();l.cover=cover;render();changed()}catch(err){toast(err.message)}finally{e.target.value=''}};

window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===parent&&e.data?.type==='retro-pause-media')stopMedia()});

$('#componentsBtn').onclick=()=>$('#componentsDialog').showModal();

window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===$('#componentsDialog iframe').contentWindow&&e.data?.type==='paperplay-close-library')$('#componentsDialog').close()});
